@mallexxx 
I am not sure if there was a reason for not doing it, but could we instead do the following in `ConfigurationFetcher`?

```
public func fetch(_ configuration: Configuration, isDebug: Bool = false) async throws {
        let requirements: APIResponseRequirements = isDebug ? .requireNonEmptyData : .allowHTTPNotModified
        let fetchResult = try await fetch(from: configuration.url, withEtag: etag(for: configuration), requirements: requirements)
        if let data = fetchResult.data {
            try validator.validate(data, for: configuration)
        }
        try store(fetchResult, for: configuration)
    }
```
basically
having `let requirements: APIResponseRequirements = isDebug ? .requireNonEmptyData : .allowHTTPNotModified`
instead of  ` let requirements: APIResponseRequirements = isDebug ? .requireNonEmptyData : .default`

